    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==bg or (r,c) in seen: continue
            q=[(r,c)]; cells=[]
            while q:
                y,x=q.pop()
                if (y,x) in seen: continue
                seen.add((y,x)); cells.append((y,x,g[y][x]))
